script:
export const meta = {
  name: 'W913-复审',
  description: 'W913 定稿之复审：只攻首审後之 39 处改与新立之环12（圣经之补）→ 纳防再定稿（⛔施）',
  phases: [
    { title: '复审', detail: '二攻者' },
    { title: '定', detail: '纳防·重算审之指' },
  ],
}
const S = '/tmp/claude-0/-home-user/fc87a25e-bbf0-5a31-be3f-8a53382aa0f0'
const WT = S + '/scratchpad/wt913'
const PLAN = WT + '/设定/方案/W913.md'
const ENV = `
【境】施工之树：${WT}（今＝主枝 9e2b48095，含 W911 之预审之律与 480 段案之正〔造式验.段案之免、章料.禁之印、剧情全图.撞之注〕）。方案：${PLAN}（定稿·约 99KB）。首审之果（三攻者 39 险·判须改）：${S}/tasks/wndp1z0y3.output（result.atks 与 result.fin）。
⛔git commit/push/checkout/stash/reset；⛔动 /home/user/the-novel 与他树；试於 /tmp 之副本，试毕必删（rm -rf）。零 token 之器只读只跑。文风：仓之文风（简、文言之词）。
质之铁律：⛔伤书之质、⛔拖累写书（写书之坐之读每席 ≤千字）。480 已於 15:04 派出在写；W913 唯 480 封後入主，首用之章 481。`
const RISKS = { type: 'object', properties: {
  risks: { type: 'array', description: 'risks', items: { type: 'object', properties: {
    risk: { type: 'string', description: '险' }, ring: { type: 'string', description: '环N 或 取' },
    evidence: { type: 'string', description: '据（档:行、实跑之令与其果）' }, defense: { type: 'string', description: '防（可施、有锚）' } },
    required: ['risk', 'ring', 'evidence', 'defense'] } },
  verdict: { type: 'string', description: '判：可施／须改（书其由）' } }, required: ['risks', 'verdict'] }

phase('复审')
const LENS = [
  { key: '改之真', p: '首审 39 险之防是否真落於方案之环（逐条对：防所书 ↔ 方案今文），落而生新病否（改与改相撞、与既有之器相悖、与 480 段案之正之 段案之免 一把否）；尤查：执笔任单只收三类後 ≤880 字之实算、对账 ✓／⛔ 起行与 --前 --红、节题常量、段料第五级舍、回放之器与时点之料。' },
  { key: '环12与入主', p: '新立之环12「圣经之补」（首审未攻）：其器只察只指之真否、剧情庭481「〇、先裁」之接线（剧情庭之席与段料是否真读之）、改单 --施单 --落 之路、⛔器改圣经之文之守、写者之窗与章-N 串行之实；并「取」之入主之序（480 封→大审480 --包 之前之窗、与 W912/W914/W915 之并序）、真用之验首章 481 之据。' },
]
const atks = await parallel(LENS.map(l => () => agent(`${ENV}
【汝之职】复审之攻者（只读）——汝之眼：${l.key}。${l.p}
先读首审之果之 fin 与方案全文之相关诸环，再读其所引之档与器以实证（可於 /tmp 副本实跑）。只报真险：每险有据（档:行或实跑之果）、有可施之防（有锚、⛔以否定起首）；⛔复述首审已防且今文确已落者。险至多 8 条；无真险即 risks 空、判「可施」。`, { label: `复审:${l.key}`, phase: '复审', schema: RISKS })))

phase('定')
const live = atks.filter(Boolean)
const fin = await agent(`${ENV}
【汝之职】定：纳复审之防於方案 ${PLAN}（只改此档）。
复审之果：${JSON.stringify(live)}
一、逐险或纳（改其环之文）或驳（书由於注）；纳者改相应之环（做什么、确证、败则）。
二、「## 预审」一节：预审者之行改作「- 预审者：wf_33599ddb-aed、wf_复审待补（首审攻者 3；复审攻者 ${live.length}）」；复审每险各添一行，式照既有之险行「- 险（环N｜取）：…｜防：…」（防⛔以否定起首、须有锚）；判之行：复审有「须改」者书「- 判：须改→已改 环…」（列首审与复审所改之环之并），俱可施者照旧。
三、改毕跑 cd ${WT} && python3 工具/方案.py --预审之指 W913，以其所印更「- 审之指：」之行；再跑 python3 工具/方案.py --验 W913 须 ✓（唯「wf_复审待补」致之坏可许——书之）。
四、⛔改他档；/tmp 之副本必删。返：所纳、所驳（由）、验之果。`, { label: '定:W913', phase: '定', schema: { type: 'object', properties: {
  adopted: { type: 'number', description: '纳' }, rejected: { type: 'number', description: '驳' }, gist: { type: 'string', description: '要' } }, required: ['adopted', 'rejected', 'gist'] } })
return { atks: live, fin }
